def simulate_robot(instructions):
    x, y = 0, 0
    for instruction in instructions:
        if instruction == 'L':
            if y > 0:
                y -= 1
            elif y < 0:
                y += 1
        elif instruction == 'R':
            if y > 0:
                y += 1
            elif y < 0:
                y -= 1
        elif instruction == 'F' and y > 0:
            x += 1
        elif instruction == 'F' and y < 0:
            x -= 1
        elif instruction == 'F' and x > 0:
            y += 1
        elif instruction == 'F' and x < 0:
            y -= 1
    return (x, y)

instructions = ["L", "F", "R", "F", "F", "F"]
final_position = simulate_robot(instructions)
print(final_position)
```

