# Function to turn and move the robot
def move_robot():
    global x, y, direction
    if direction == 'N':
        y += 3
    elif direction == 'E':
        x += 3
    elif direction == 'S':
        y -= 3
    elif direction == 'W':
        x -= 3
    else:
        print("Invalid direction")

    # Turn the robot
    if direction == 'N':
        direction = 'E'
    elif direction == 'E':
        direction = 'S'
    elif direction == 'S':
        direction = 'W'
    elif direction == 'W':
        direction = 'N'

# Process each instruction
for instruction in instructions:
    move_robot()

print((x, y))
