def simulate_robot(instructions):
    # Initialize starting position and direction
    x, y = 0, 0
    direction = 'N'  # Start facing north

    # Process each instruction
    for instruction in instructions:
        if instruction == 'L':  # Turn left
            if direction == 'N':
                direction = 'W'
            elif direction == 'W':
                direction = 'S'
            elif direction == 'S':
                direction = 'E'
            else:
                direction = 'N'
        elif instruction == 'R':  # Turn right
            if direction == 'N':
                direction = 'E'
            elif direction == 'W':
                direction = 'N'
            elif direction == 'S':
                direction = 'W'
            else:
                direction = 'S'
        elif instruction == 'F':  # Walk forward
            if direction == 'N':
                y += 1
            elif direction == 'S':
                y -= 1
            elif direction == 'E':
                x += 1
            else:
                x -= 1

    return (x, y)

# Instructions
instructions = ['L', 'R', 'L', 'L', 'F', 'F']

# Simulate and print the final position
final_position = simulate_robot(instructions)
print(final_position)  # Output: (0, 2)
```

