def simulate_robot_instructions():
    # Initialize the starting position and direction
    x, y = 0, 0
    direction = 'N'  # Start facing north

    # Instructions
    instructions = [
        'turn left', 'turn left', 'walk forward 2 steps', 'walk forward 2 steps', 'walk forward 1 step', 'turn right'
    ]

    for instruction in instructions:
        if instruction == 'turn left':
            if direction == 'N':
                direction = 'W'
            elif direction == 'W':
                direction = 'S'
            elif direction == 'S':
                direction = 'E'
            else:
                direction = 'N'
        elif instruction == 'turn right':
            if direction == 'N':
                direction = 'E'
            elif direction == 'W':
                direction = 'N'
            elif direction == 'S':
                direction = 'W'
            else:
                direction = 'S'
        else:  # walk forward
            if direction == 'N':
                y += 1
            elif direction == 'S':
                y -= 1
            elif direction == 'E':
                x += 1
            else:
                x -= 1

    return (x, y)

# Simulate the robot's instructions and print the final position
print(simulate_robot_instructions())  # Output should be (1, 1)
```

