def simulate_robot(instructions):
    x, y = 0, 0
    direction = 0  # 0: north, 1: east, 2: south, 3: west

    for instruction in instructions:
        if instruction == 'F':
            if direction == 0:
                y += 1
            elif direction == 1:
                x += 1
            elif direction == 2:
                y -= 1
            elif direction == 3:
                x -= 1
        elif instruction == 'L':
            direction = (direction + 2) % 4
        elif instruction == 'R':
            direction = (direction + 1) % 4

    return (x, y)

instructions = ['F', 'F', 'F', 'F', 'F', 'L']
print(simulate_robot(instructions))  # Output: (2, 2)
```

