# Function to turn the robot
def turn(direction, angle):
    angle = angle % 360  # Normalize the angle
    if angle == 180:
        return direction + 2
    elif angle == 90:
        return direction + 1
    elif angle == 0:
        return direction - 1
    elif angle == 270:
        return direction - 2

# Function to move the robot
def move(direction):
    global position, direction
    if direction == 0:
        position[1] += 1  # North
    elif direction == 1:
        position[0] += 1  # East
    elif direction == 2:
        position[1] -= 1  # South
    elif direction == 3:
        position[0] -= 1  # West

# Process the instructions
