    ('walk forward', 1),
    ('walk forward', 4),
    ('walk forward', 4),
    ('turn right', 1),
    ('turn right', 1)
]

# Function to move in the current direction
def move(position, direction, steps):
    x, y = position
    if direction == 'north':
        for _ in range(steps):
            y += 1
            yield x, y
    elif direction == 'east':
        for _ in range(steps):
            x += 1
            yield x, y

# Function to turn the robot
def turn_right(current_direction):
    if current_direction == 'north':
        return 'west'
    elif current_direction == 'east':
        return 'north'
    elif current_direction == 'south':
        return 'east'
    elif current_direction == 'west':
        return 'south'

# Process each instruction
for instruction, steps in instructions:
    if instruction == 'walk forward':
        for x, y in move(position, direction, steps):
            position = x, y
    elif instruction == 'turn right':
        direction = turn_right(direction)

# Final position
print(position)
