    if instruction == 0:
        return (direction + 1) % 4
    elif instruction == 1:
        return (direction + 3) % 4
    elif instruction == 2:
        return (direction + 2) % 4
    elif instruction == 3:
        return (direction + 1) % 4

# Function to walk forward a given number of steps
def walk(steps, direction):
    if steps == 0:
        return
    elif steps < 0:
        return
    for _ in range(abs(steps)):
        if direction == 0:
            y += 1
        elif direction == 1:
            x += 1
        elif direction == 2:
            y -= 1
        elif direction == 3:
            x -= 1

# Execute the instructions
