        robot_direction = (robot_direction - 1) % 4
    elif instruction['instruction'] == 'walk forward':
        if robot_direction == 0:
            robot_position[1] += instruction['steps']
        elif robot_direction == 1:
            robot_position[0] += instruction['steps']
        elif robot_direction == 2:
            robot_position[1] -= instruction['steps']
        elif robot_direction == 3:
            robot_position[0] -= instruction['steps']

# Print the final position
